function rcHtml(tag,attrs,content){var el=document.createElement(tag);Object.keys(attrs||{}).forEach(function(k){el.setAttribute(k,attrs[k])});el.innerHTML=content||'';return el}
function rcEnsureNav(){var nav=document.getElementById('teacherNav');if(!nav)return;var b=nav.querySelector('[data-view="readyClass"]');if(!b){b=document.createElement('button');b.type='button';b.dataset.view='readyClass';b.innerHTML='🎬 <span>Ready Class</span>';var anchor=nav.querySelector('[data-view="lessons"]')||nav.querySelector('[data-view="courses"]');if(anchor)nav.insertBefore(b,anchor);else nav.appendChild(b)}b.hidden=false;b.style.removeProperty('display');b.setAttribute('aria-label','Ready Class — biblioteca de aulas interativas');b.onclick=function(e){if(e)e.preventDefault();rcOpenPage()}}
