function rcSetPage(){try{currentView='readyClass'}catch(e){}document.querySelectorAll('#teacherNav [data-view]').forEach(function(b){b.classList.toggle('active',b.dataset.view==='readyClass')});if(typeof setPage==='function')setPage('Ready Class','Importe, organize, ministre e compartilhe aulas HTML interativas.','<button class="btn primary" onclick="window.rcOpenEditor()">＋ Nova aula HTML</button>');else{var t=document.getElementById('pageTitle');if(t)t.textContent='Ready Class'}}
async function rcOpenPage(){try{sessionStorage.setItem('tic-last-view','readyClass')}catch(e){}if(!rcUid()){try{if(typeof sb!=='undefined'&&sb&&sb.auth&&typeof sb.auth.getSession==='function'){var authResult=await sb.auth.getSession();var authSession=authResult&&authResult.data&&authResult.data.session;if(authSession&&authSession.user&&authSession.user.id)rcState.authUserId=authSession.user.id}}catch(authError){console.warn('[Ready Class] não foi possível recuperar sessão pelo Supabase Auth',authError)}}if(!rcUid()){rcToast('Sua sessão não foi identificada pelo Supabase. Não saí da página nem alterei seus dados. Atualize a página e, se necessário, entre novamente.','error');return}rcSetPage();var root=rcRoot();if(!root){console.error('[Ready Class] #content não encontrado');rcToast('Não encontrei a área principal da página (#content). Atualize a plataforma.','error');return}root.innerHTML='<div id="readyClassApp"><div class="rc-hero"><div><h2>🎬 Ready Class</h2><p>Interactive Lesson Studio · Biblioteca, viewer e acompanhamento.</p></div><div class="rc-hero-actions"><button class="rc-btn" onclick="window.rcImportSample()">✨ Importar exemplo A0</button><button class="rc-btn primary" onclick="window.rcOpenEditor()">＋ Nova aula HTML</button></div></div><div class="rc-tabs"><button class="active" data-rc-tab="library">📚 Minhas aulas</button><button data-rc-tab="shares">🔗 Links compartilhados</button><button data-rc-tab="insights">📊 Student Insights</button></div><div id="rcTabContent"><div class="rc-empty">Carregando sua biblioteca…</div></div></div>';root.querySelectorAll('[data-rc-tab]').forEach(function(b){b.onclick=function(){rcState.activeTab=b.dataset.rcTab;root.querySelectorAll('[data-rc-tab]').forEach(function(x){x.classList.toggle('active',x===b)});rcRenderTab()}});return rcLoadAll()}
async function rcLoadAll(){if(rcState.loading)return;var uid=rcUid();if(!uid){var host=document.getElementById('rcTabContent');if(host)host.innerHTML='<div class="rc-empty">Sua sessão expirou. Atualize a página e entre novamente.</div>';return}rcState.loading=true;var host=document.getElementById('rcTabContent');if(host)host.innerHTML='<div class="rc-empty">Carregando aulas e sessões…</div>';try{var results=await Promise.all([sb.from('tic_ready_classes').select('id,title,description,cefr_level,skills,duration_minutes,source_filename,html_version,active,created_at,updated_at,folder_id,teacher_state').eq('teacher_id',uid).order('updated_at',{ascending:false}),sb.from('tic_ready_class_shares').select('id,ready_class_id,student_id,class_id,expires_at,max_sessions,active,created_at').eq('teacher_id',uid).order('created_at',{ascending:false}),sb.from('tic_ready_class_sessions').select('id,share_id,ready_class_id,student_id,student_name,started_at,last_seen_at,completed_at,current_section,progress_percent,score,score_total').eq('teacher_id',uid).order('started_at',{ascending:false}).limit(150),sb.from('tic_students').select('id,display_name,current_level,status').eq('teacher_id',uid).order('display_name'),sb.from('tic_classes').select('id,name,level,status').eq('teacher_id',uid).order('name'),sb.from('tic_ready_class_folders').select('id,name,color,teacher_id').eq('teacher_id',uid).order('name')]);results.forEach(function(r){if(r.error)throw r.error});rcState.classes=results[0].data||[];rcState.shares=results[1].data||[];rcState.sessions=results[2].data||[];rcState.students=results[3].data||[];rcState.classesList=results[4].data||[];rcState.folders=results[5].data||[];rcRenderTab()}catch(e){console.error('[Ready Class]',e);if(host)host.innerHTML='<div class="rc-empty"><h3>Não foi possível carregar Ready Class</h3><p>'+rcEsc(e.message||'Erro de conexão')+'</p><button class="rc-btn primary" onclick="window.rcLoadAll()">↻ Tentar novamente</button></div>'}finally{rcState.loading=false}}
